package com.runanywhere.sdk.foundation.security

import android.content.Context
import android.util.AtomicFile
import java.io.File
import java.io.FileOutputStream
import java.io.IOException
import java.nio.charset.StandardCharsets
import java.security.MessageDigest

/** Atomic ciphertext storage excluded from Android backup and device transfer. */
internal class NoBackupCiphertextStore(
    context: Context,
    directoryName: String,
) {
    private val directory = File(context.noBackupFilesDir, directoryName)

    init {
        require(directoryName.matches(SAFE_DIRECTORY_NAME)) { "Invalid secure-storage directory name" }
    }

    fun read(key: String): ByteArray? =
        synchronized(IO_LOCK) {
            val entry = entryFile(key)
            if (!entry.exists() && !backupFile(entry).exists()) return@synchronized null
            AtomicFile(entry).openRead().use { it.readBytes() }
        }

    fun write(key: String, value: ByteArray): Boolean =
        synchronized(IO_LOCK) {
            ensureDirectory()
            val atomicFile = AtomicFile(entryFile(key))
            var output: FileOutputStream? = null
            try {
                output = atomicFile.startWrite()
                output.write(value)
                atomicFile.finishWrite(output)
                true
            } catch (exception: Exception) {
                atomicFile.failWrite(output)
                throw exception
            }
        }

    fun delete(key: String): Boolean =
        synchronized(IO_LOCK) {
            val entry = entryFile(key)
            AtomicFile(entry).delete()
            !entry.exists() && !backupFile(entry).exists() && !newFile(entry).exists()
        }

    fun clear(): Boolean =
        synchronized(IO_LOCK) {
            if (!directory.exists()) return@synchronized true
            val entries = directory.listFiles() ?: return@synchronized false
            entries.fold(true) { allDeleted, entry -> entry.delete() && allDeleted } && directory.delete()
        }

    private fun entryFile(key: String): File = File(directory, sha256(key))

    private fun ensureDirectory() {
        if ((!directory.exists() && !directory.mkdirs()) || !directory.isDirectory) {
            throw IOException("Unable to open secure-storage directory")
        }
    }

    private companion object {
        val SAFE_DIRECTORY_NAME = Regex("[A-Za-z0-9._-]+")
        val IO_LOCK = Any()
        val HEX = "0123456789abcdef".toCharArray()

        fun backupFile(entry: File): File = File(entry.path + ".bak")

        fun newFile(entry: File): File = File(entry.path + ".new")

        fun sha256(value: String): String {
            val digest = MessageDigest.getInstance("SHA-256").digest(value.toByteArray(StandardCharsets.UTF_8))
            return buildString(digest.size * 2) {
                digest.forEach { byte ->
                    val unsigned = byte.toInt() and 0xff
                    append(HEX[unsigned ushr 4])
                    append(HEX[unsigned and 0x0f])
                }
            }
        }
    }
}

import {
  LoggingManager,
  sanitizeLogMessage,
  type LogDestination,
  type LogEntry,
} from '../../src/Foundation/Logging/Services/LoggingManager';
import { SDKLogger } from '../../src/Foundation/Logging/Logger/SDKLogger';

describe('SDKLogger secret safety', () => {
  test('logError keeps arbitrary exception and context values out of destinations', () => {
    const entries: LogEntry[] = [];
    const consoleError = jest.spyOn(console, 'error').mockImplementation(() => undefined);
    const destination: LogDestination = {
      identifier: 'sdk-logger-security-test',
      isAvailable: true,
      write: (entry) => entries.push(entry),
      flush: () => undefined,
    };
    LoggingManager.shared.addDestination(destination);
    try {
      new SDKLogger('SecurityTest').logError(
        new Error('request failed with opaque-mobile-key-123'),
        'Authorization: opaque-mobile-key-123'
      );
    } finally {
      LoggingManager.shared.removeDestination(destination);
    }

    expect(entries).toHaveLength(1);
    expect(entries[0]?.message).toBe('SDK operation failed');
    expect(entries[0]?.metadata).toMatchObject({
      error_name: 'Error',
      context_provided: true,
    });
    expect(JSON.stringify(entries[0])).not.toContain('opaque-mobile-key-123');
    expect(JSON.stringify(consoleError.mock.calls)).not.toContain('opaque-mobile-key-123');
    consoleError.mockRestore();
  });

  test('redacts secret-bearing free-form message text while preserving context', () => {
    const raw =
      'Cloud provider failed at https://api.example.test/v1/transcribe' +
      '?api_key=opaque-query-key with Authorization: Bearer opaque-bearer-token, ' +
      'token=opaque-token password="opaque password" and sk-abcdefgh12345678';

    const sanitized = sanitizeLogMessage(raw);

    expect(sanitized).toContain(
      'Cloud provider failed at https://api.example.test/v1/transcribe'
    );
    expect(sanitized).toContain('api_key=[REDACTED]');
    expect(sanitized).toContain('Authorization: [REDACTED]');
    expect(sanitized).toContain('token=[REDACTED]');
    expect(sanitized).toContain('password=[REDACTED]');
    expect(sanitized).toContain('[REDACTED-KEY]');
    for (const secret of [
      'opaque-query-key',
      'opaque-bearer-token',
      'opaque-token',
      'opaque password',
      'sk-abcdefgh12345678',
    ]) {
      expect(sanitized).not.toContain(secret);
    }
  });

  test('sanitizes representative interpolated errors before every destination', () => {
    const entries: LogEntry[] = [];
    const secret = 'provider-secret-123';
    const consoleError = jest
      .spyOn(console, 'error')
      .mockImplementation(() => undefined);
    const destination: LogDestination = {
      identifier: 'sdk-logger-message-security-test',
      isAvailable: true,
      write: (entry) => entries.push(entry),
      flush: () => undefined,
    };
    LoggingManager.shared.addDestination(destination);
    try {
      const providerError = new Error(
        `request failed: password=${secret}; ` +
          `https://user:${secret}@api.example.test/v1`
      );
      new SDKLogger('CloudSTT').error(
        `cloud provider handler failed: ${providerError.message}`,
        { detail: `access_token=${secret}` }
      );
    } finally {
      LoggingManager.shared.removeDestination(destination);
      consoleError.mockRestore();
    }

    expect(entries).toHaveLength(1);
    expect(entries[0]?.message).toContain('cloud provider handler failed');
    expect(entries[0]?.message).not.toContain(secret);
    expect(entries[0]?.message).toContain('password=[REDACTED]');
    expect(entries[0]?.message).toContain(
      'https://[REDACTED]@api.example.test/v1'
    );
    expect(entries[0]?.metadata).toEqual({
      detail: 'access_token=[REDACTED]',
    });
  });

  test('recursively sanitizes strings and sensitive keys inside metadata arrays', () => {
    const entries: LogEntry[] = [];
    const consoleError = jest.spyOn(console, 'error').mockImplementation(() => undefined);
    const destination: LogDestination = {
      identifier: 'sdk-logger-array-security-test',
      isAvailable: true,
      write: (entry) => entries.push(entry),
      flush: () => undefined,
    };
    LoggingManager.shared.addDestination(destination);
    try {
      new SDKLogger('SecurityTest').error('nested metadata', {
        attempts: [
          'Authorization: Bearer top-level-array-secret',
          [{ detail: 'token=nested-array-secret', apiKey: 'key-secret' }],
        ],
      });
    } finally {
      LoggingManager.shared.removeDestination(destination);
      consoleError.mockRestore();
    }

    expect(entries[0]?.metadata).toEqual({
      attempts: [
        'Authorization: [REDACTED]',
        [{ detail: 'token=[REDACTED]', apiKey: '[REDACTED]' }],
      ],
    });
    expect(JSON.stringify(entries[0])).not.toContain('array-secret');
    expect(JSON.stringify(entries[0])).not.toContain('key-secret');
  });
});

import { beforeEach, describe, expect, it, vi } from 'vitest';
import { AudioEncoding } from '@runanywhere/proto-ts/model_types';

const mocks = vi.hoisted(() => ({
  captures: [] as Array<{
    emit: (chunk: Float32Array) => void;
    clearCount: number;
    capturing: boolean;
    stopCount: number;
  }>,
  captureStart: null as Promise<void> | null,
  playback: {
    play: vi.fn(),
    playEncoded: vi.fn(),
    stop: vi.fn(),
    dispose: vi.fn(),
  },
  feedVoiceAgentAudio: vi.fn(),
  supportsVoiceAgentFeedAudio: vi.fn(() => true),
  float32ToPcm16: vi.fn((samples: Float32Array) => new Uint8Array(samples.length * 2)),
}));

vi.mock('../../../src/Infrastructure/AudioCapture', () => ({
  AudioCapture: class {
    private chunkCallback: ((chunk: Float32Array) => void) | undefined;
    private state = {
      emit: (chunk: Float32Array): void => this.chunkCallback?.(chunk),
      clearCount: 0,
      capturing: false,
      stopCount: 0,
    };

    constructor() {
      mocks.captures.push(this.state);
    }

    get isCapturing(): boolean { return this.state.capturing; }

    async start(onChunk?: (chunk: Float32Array) => void): Promise<void> {
      this.chunkCallback = onChunk;
      if (mocks.captureStart) await mocks.captureStart;
      this.state.capturing = true;
    }

    stop(): void {
      this.state.stopCount += 1;
      this.state.capturing = false;
    }
    clearBuffer(): void { this.state.clearCount += 1; }
  },
}));

vi.mock('../../../src/Infrastructure/AudioPlayback', () => ({
  AudioPlayback: class {
    play = mocks.playback.play;
    playEncoded = mocks.playback.playEncoded;
    stop = mocks.playback.stop;
    dispose = mocks.playback.dispose;
  },
}));

vi.mock('../../../src/Public/Extensions/RunAnywhere+AudioConvert', () => ({
  float32ToPcm16: mocks.float32ToPcm16,
}));

vi.mock('../../../src/Public/Extensions/RunAnywhere+VoiceAgent', () => ({
  feedVoiceAgentAudio: mocks.feedVoiceAgentAudio,
  supportsVoiceAgentFeedAudio: mocks.supportsVoiceAgentFeedAudio,
}));

import { VoiceAgentMicDriver } from '../../../src/Infrastructure/VoiceAgentMicDriver';

function deferred<T>(): {
  promise: Promise<T>;
  resolve: (value: T) => void;
} {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>((done) => { resolve = done; });
  return { promise, resolve };
}

function turnResult() {
  return {
    speechDetected: true,
    transcription: 'hello',
    assistantResponse: 'hi there',
    synthesizedAudio: new Uint8Array(3_200),
    synthesizedAudioSampleRateHz: 16_000,
    synthesizedAudioChannels: 1,
    synthesizedAudioEncoding: AudioEncoding.AUDIO_ENCODING_PCM_S16_LE,
    sessionId: 'test',
    turnId: 'turn',
    sttTimeMs: 1,
    llmTimeMs: 1,
    ttsTimeMs: 1,
    totalTimeMs: 3,
    errorCode: 0,
  };
}

async function flush(): Promise<void> {
  await Promise.resolve();
  await Promise.resolve();
  await Promise.resolve();
  await new Promise((resolve) => setTimeout(resolve, 25));
}

describe('VoiceAgentMicDriver', () => {
  beforeEach(() => {
    mocks.captures.length = 0;
    mocks.captureStart = null;
    mocks.playback.play.mockReset();
    mocks.playback.playEncoded.mockReset();
    mocks.playback.stop.mockReset();
    mocks.playback.dispose.mockReset();
    mocks.feedVoiceAgentAudio.mockReset();
    mocks.supportsVoiceAgentFeedAudio.mockReset();
    mocks.supportsVoiceAgentFeedAudio.mockReturnValue(true);
    mocks.float32ToPcm16.mockClear();
  });

  it('fails explicitly when commons feed audio is unavailable', async () => {
    mocks.supportsVoiceAgentFeedAudio.mockReturnValue(false);
    const driver = new VoiceAgentMicDriver();
    await expect(driver.start()).rejects.toMatchObject({
      message: expect.stringContaining('VoiceAgentMicDriver'),
      proto: {
        nestedMessage: expect.stringContaining('rac_voice_agent_feed_audio_proto'),
      },
    });
  });

  it('feeds captured PCM into commons and plays synthesized replies', async () => {
    const playback = deferred<void>();
    mocks.feedVoiceAgentAudio
      .mockResolvedValueOnce(null)
      .mockResolvedValueOnce(turnResult());
    mocks.playback.playEncoded.mockReturnValue(playback.promise);
    const phases: string[] = [];
    const turns: Array<{ userText: string; assistantText: string }> = [];
    const driver = new VoiceAgentMicDriver();
    await driver.start({
      onPhase: (phase) => phases.push(phase),
      onTurn: (turn) => { turns.push(turn); },
    });

    const capture = mocks.captures.at(-1)!;
    capture.emit(new Float32Array(1_600).fill(0.1));
    await flush();
    capture.emit(new Float32Array(1_600).fill(0.2));
    await flush();

    expect(mocks.float32ToPcm16).toHaveBeenCalled();
    expect(mocks.feedVoiceAgentAudio).toHaveBeenCalled();
    expect(turns).toEqual([{ userText: 'hello', assistantText: 'hi there' }]);
    expect(mocks.playback.playEncoded).toHaveBeenCalledOnce();
    expect(phases).toContain('listening');
    expect(phases).toContain('speaking');

    playback.resolve();
    await flush();
    expect(phases.at(-1)).toBe('listening');
  });

  it('drops an in-flight playout after stop/restart instead of leaking old playback', async () => {
    const inference = deferred<ReturnType<typeof turnResult> | null>();
    mocks.feedVoiceAgentAudio.mockReturnValue(inference.promise);
    mocks.playback.playEncoded.mockResolvedValue(undefined);
    const onTurn = vi.fn();
    const driver = new VoiceAgentMicDriver();
    await driver.start({ onTurn });
    mocks.captures.at(-1)!.emit(new Float32Array(1_600).fill(0.2));
    await flush();

    driver.stop();
    expect(mocks.playback.dispose).toHaveBeenCalledOnce();
    await driver.start({ onTurn });
    inference.resolve(turnResult());
    await flush();

    expect(onTurn).not.toHaveBeenCalled();
    expect(mocks.playback.playEncoded).not.toHaveBeenCalled();
  });

  it('closes capture when microphone permission resolves after stop', async () => {
    const permission = deferred<void>();
    mocks.captureStart = permission.promise;
    const phases: string[] = [];
    const driver = new VoiceAgentMicDriver();

    const starting = driver.start({ onPhase: (phase) => phases.push(phase) });
    await flush();
    const capture = mocks.captures.at(-1)!;
    driver.stop();
    permission.resolve();
    await starting;

    expect(capture.stopCount).toBe(2);
    expect(capture.capturing).toBe(false);
    expect(phases).not.toContain('listening');
  });
});

import {
  expect,
  test as base,
  type BrowserContext,
  type Locator,
  type Page,
  type TestInfo,
} from '@playwright/test';
import { existsSync } from 'node:fs';
import { resolve } from 'node:path';

export const RELEASE_E2E_ENABLED = process.env.RA_RUN_FULL_E2E === '1';
const CONFIGURED_BASE_URL = process.env.RA_E2E_BASE_URL;
const TARGETS_REMOTE_ORIGIN = Boolean(
  CONFIGURED_BASE_URL
  && !/^https?:\/\/(?:localhost|127\.0\.0\.1|\[::1\])(?::|\/|$)/i.test(CONFIGURED_BASE_URL),
);
const RELEASE_TRACE_ENABLED = process.env.RA_E2E_TRACE === '1'
  && !TARGETS_REMOTE_ORIGIN;

export const AUDIO_FIXTURE = resolve(__dirname, '../fixtures/weather-command.wav');
export const IMAGE_FIXTURE = resolve(__dirname, '../fixtures/release-image.jpg');
export const RAG_FIXTURE = resolve(__dirname, '../fixtures/release-rag.txt');

