type DiagnosticKind =
  | `console.${string}`
  | 'pageerror'
  | 'requestfailed'
  | 'http'
  | 'pagecrash';

export interface BrowserDiagnostic {
  at: string;
  kind: DiagnosticKind;
  message: string;
  method?: string;
  resourceType?: string;
  status?: number;
  url?: string;
  expected?: boolean;
}

interface ExpectedFailureScope {
  pattern: RegExp;
  matches: number;
}

const expectedFailureScopes = new WeakMap<Page, ExpectedFailureScope[]>();

interface BrowserSDKProbe {
  isInitialized?: boolean;
  getModel?: (modelId: string) => {
    category?: unknown;
    isDownloaded?: boolean;
    localPath?: string;
  } | null;
  downloadedModels?: () => {
    models?: Array<{ id?: string; category?: unknown; localPath?: string }>;
  } | null;
  listModels?: () => {
    models?: Array<{ id?: string; category?: unknown }>;
  } | null;
  currentModel?: (options: {
    category: unknown;
    includeModelMetadata: boolean;
  }) => { modelId?: string } | null;
}

interface ReleaseSession {
  context: BrowserContext;
  page: Page;
  events: BrowserDiagnostic[];
}

interface ReleaseTestFixtures {
  releaseArtifacts: void;
}

interface ReleaseWorkerFixtures {
  releaseSession: ReleaseSession;
  appPage: Page;
}

/**
 * The release suite deliberately shares this worker-scoped page/context.
 * Playwright's normal `page` fixture creates a new context for every test,
 * which would discard OPFS and force every modality to redownload its model.
 */
export const test = base.extend<ReleaseTestFixtures, ReleaseWorkerFixtures>({
  releaseSession: [async ({ browser }, use, workerInfo) => {
    const configuredBaseURL = workerInfo.project.use.baseURL;
    const baseURL = typeof configuredBaseURL === 'string'
      ? configuredBaseURL
      : 'http://localhost:3000';
    const context = await browser.newContext({
      baseURL,
      viewport: { width: 1440, height: 1000 },
      permissions: ['microphone', 'camera', 'clipboard-read', 'clipboard-write'],
      acceptDownloads: true,
      serviceWorkers: 'allow',
    });
    const page = await context.newPage();
    const events = observeBrowserDiagnostics(page);

    // The default Playwright trace option only instruments its built-in page
    // fixture. This context is custom, so trace it explicitly and create one
    // chunk per named release test in the automatic fixture below.
    if (RELEASE_TRACE_ENABLED) {
      await context.tracing.start({ screenshots: true, snapshots: true, sources: true });
    }
    try {
      await use({ context, page, events });
    } finally {
      if (RELEASE_TRACE_ENABLED) {
        await context.tracing.stop().catch(() => undefined);
      }
      let closeTimeout: ReturnType<typeof setTimeout> | undefined;
      try {
        await Promise.race([
          context.close().catch(() => undefined),
          new Promise<void>((resolveClose) => {
            closeTimeout = setTimeout(resolveClose, 30_000);
          }),
        ]);
      } finally {
        if (closeTimeout !== undefined) clearTimeout(closeTimeout);
      }
    }
  }, { scope: 'worker' }],

  appPage: [async ({ releaseSession }, use) => {
    await use(releaseSession.page);
  }, { scope: 'worker' }],

  releaseArtifacts: [async ({ releaseSession }, use, testInfo) => {
    const { context, page, events } = releaseSession;
    const eventOffset = events.length;
    let traceChunkStarted = false;

    if (RELEASE_TRACE_ENABLED) {
      try {
        await context.tracing.startChunk({ title: testInfo.titlePath.join(' > ') });
        traceChunkStarted = true;
      } catch {
        // A page crash still needs the diagnostics/screenshot attempt below.
      }
    }

    try {
      await use();
    } finally {
      // Defense-in-depth: clear the session-only Settings password field before
      // any automatic screenshot or trace artifact.
      await scrubPasswordInputs(page);
      const diagnostics = events.slice(eventOffset);
      const snapshot = await collectRuntimeSnapshot(page);
      await attachJSON(testInfo, 'browser-diagnostics', { diagnostics, snapshot });

      if (!page.isClosed()) {
        const screenshotPath = testInfo.outputPath('checkpoint.png');
        const captured = await page.screenshot({
          path: screenshotPath,
          fullPage: true,
          animations: 'disabled',
          caret: 'hide',
          timeout: 30_000,
        }).then(() => true).catch(() => false);
        if (captured) {
          await testInfo.attach('checkpoint', {
            path: screenshotPath,
            contentType: 'image/png',
          });
        }
      }

      if (traceChunkStarted) {
        const tracePath = testInfo.outputPath('trace.zip');
        const traced = await context.tracing.stopChunk({ path: tracePath })
          .then(() => true)
          .catch(() => false);
        if (traced) {
          await testInfo.attach('trace', {
            path: tracePath,
            contentType: 'application/zip',
          });
        }
      }

      const unexpected = diagnostics.filter(isUnexpectedFailure);
      expect.soft(
        unexpected,
        `Unexpected browser failures:\n${unexpected.map(formatDiagnostic).join('\n')}`,
      ).toEqual([]);
    }
  }, { auto: true }],
});

export { expect };

export function assertFixtureFiles(): void {
  for (const fixture of [AUDIO_FIXTURE, IMAGE_FIXTURE, RAG_FIXTURE]) {
    expect(existsSync(fixture), `release fixture must exist: ${fixture}`).toBe(true);
  }
}

export async function waitForInteractive(page: Page): Promise<void> {
  await page.waitForFunction(() => {
    const probe = (window as Window & {
      __RUNANYWHERE_AI_READY__?: { ready?: boolean; state?: string; backend?: string };
    }).__RUNANYWHERE_AI_READY__;
    return probe?.ready === true && probe.state === 'interactive';
  }, undefined, { timeout: 180_000 });

  const snapshot = await page.evaluate(() => {
    const target = window as Window & {
      __RUNANYWHERE_AI_READY__?: { ready?: boolean; state?: string; backend?: string; error?: string };
      __RUNANYWHERE_SDK__?: { isInitialized?: boolean };
    };
    return {
      readiness: target.__RUNANYWHERE_AI_READY__,
      sdkInitialized: target.__RUNANYWHERE_SDK__?.isInitialized === true,
      crossOriginIsolated: window.crossOriginIsolated,
    };
  });

  expect(snapshot.readiness?.state).toBe('interactive');
  expect(snapshot.readiness?.backend, snapshot.readiness?.error).toBe('registered');
  expect(snapshot.sdkInitialized).toBe(true);
  expect(snapshot.crossOriginIsolated).toBe(true);
  await expect(page.locator('html')).toHaveAttribute('data-runanywhere-ai-backend', 'registered');
}

export async function navigateTo(page: Page, tab: string): Promise<void> {
  await page.evaluate((target) => {
    window.dispatchEvent(new CustomEvent('runanywhere:navigate', {
      detail: { tab: target },
    }));
  }, tab);
  await expect(page.locator(`#tab-${tab}`)).toHaveClass(/\bactive\b/);
  await expect(page.locator(`#tab-${tab}`)).toBeVisible();
}

export async function ensureModelReady(
  page: Page,
  trigger: string | Locator,
  model: { id: string; query: string },
  options: { downloadTimeout?: number; loadTimeout?: number } = {},
): Promise<void> {
  const downloadTimeout = options.downloadTimeout ?? 30 * 60_000;
  const loadTimeout = options.loadTimeout ?? 12 * 60_000;
  const sheet = page.locator('.modal-sheet');

  if (await sheet.isVisible().catch(() => false)) {
    await page.locator('#model-sheet-close').click();
    await expect(sheet).toBeHidden();
  }

  const target = typeof trigger === 'string' ? page.locator(trigger) : trigger;
  await expect(target).toBeVisible();
  await target.click();
  await expect(sheet).toBeVisible();

  const search = page.locator('#model-sheet-search');
  await expect(search).toBeVisible();
  await search.fill(model.query);
  const row = page.locator(`#model-sheet-list [data-model-id="${model.id}"]`).first();
  await expect(row, `model picker row for ${model.id}`).toBeVisible();

  if (await isModelLoaded(page, model.id)) {
    const select = row.locator(`[data-action="select"][data-model-id="${model.id}"]`);
    if (await select.isVisible().catch(() => false)) {
      await select.click();
    } else {
      await page.locator('#model-sheet-close').click();
    }
    await expect(sheet).toBeHidden();
    return;
  }

  if (!(await isModelDownloaded(page, model.id))) {
    const download = row.locator(`[data-action="download"][data-model-id="${model.id}"]`);
    await expect(download, `download action for ${model.id}`).toBeVisible();
    await download.click();
    console.info(`[release-e2e] ${model.id}: download requested`);
    await waitForModelDownload(page, row, model.id, downloadTimeout);
  }

  if (!(await isModelLoaded(page, model.id))) {
    const load = row.locator(`[data-action="load"][data-model-id="${model.id}"]`);
    await expect(load, `load action for ${model.id}`).toBeVisible({ timeout: 60_000 });
    console.info(`[release-e2e] ${model.id}: load requested`);
    await load.click();
    const loadDeadline = Date.now() + loadTimeout;
    while (true) {
      // Read the picker atomically in-page. A successful load either renders
      // a loaded action or immediately selects the model and removes the
      // sheet; retaining a Locator rooted at the replaced row can otherwise
      // wait on a detached element for the full test timeout.
      const loadState = await page.evaluate((id) => {
        const picker = document.querySelector<HTMLElement>('.modal-sheet');
        if (!picker) return { completed: true, errorText: '' };
        const actions = Array.from(
          picker.querySelectorAll<HTMLElement>('[data-model-id][data-action]'),
        );
        const loaded = actions.some((action) => (
          action.dataset.modelId === id
          && (action.dataset.action === 'select' || action.dataset.action === 'unload')
        ));
        const modelRow = Array.from(
          picker.querySelectorAll<HTMLElement>('[data-model-id]'),
        ).find((candidate) => candidate.dataset.modelId === id);
        const errorText = modelRow?.querySelector<HTMLElement>('.model-row-error')
          ?.textContent?.trim() ?? '';
        return { completed: loaded, errorText };
      }, model.id);
      if (loadState.completed) break;
      if (loadState.errorText) {
        throw new Error(`${model.id} load failed in the model picker: ${loadState.errorText}`);
      }
      if (Date.now() >= loadDeadline) {
        throw new Error(`${model.id} did not reach the visible loaded state before timeout`);
      }
      await page.waitForTimeout(1_000);
    }
    const retainedByNative = await isModelLoaded(page, model.id);
    if (!retainedByNative) {
      throw new Error(
        `${model.id} reached the visible loaded state but native lifecycle did not retain it`,
      );
    }
    console.info(`[release-e2e] ${model.id}: loaded`);
  }

  if (await sheet.isVisible().catch(() => false)) {
    const select = row.locator(`[data-action="select"][data-model-id="${model.id}"]`);
    if (await select.isVisible().catch(() => false)) {
      await select.click();
    } else {
      await page.locator('#model-sheet-close').click();
    }
  }
  await expect(sheet).toBeHidden();
  expect(await isModelDownloaded(page, model.id)).toBe(true);
  expect(await isModelLoaded(page, model.id)).toBe(true);
}

async function waitForModelDownload(
  page: Page,
  row: Locator,
  modelId: string,
  timeout: number,
): Promise<void> {
  const deadline = Date.now() + timeout;
  const retryAction = row.locator(`[data-action="download"][data-model-id="${modelId}"]`);
  let retries = 0;
  let lastProgressBucket = -1;
  let lastStatus = 'download starting';

  while (Date.now() < deadline) {
    if (await isModelDownloaded(page, modelId)) {
      console.info(`[release-e2e] ${modelId}: download persisted to OPFS`);
      return;
    }

    const snapshot = await row.evaluate((element) => {
      const progress = element.querySelector<HTMLElement>('.progress-fill')?.style.width ?? '';
      return {
        progress,
        text: (element.textContent ?? '').replace(/\s+/g, ' ').trim(),
      };
    }).catch(() => ({ progress: '', text: 'model row unavailable' }));
    lastStatus = snapshot.text;
    const progress = Number.parseFloat(snapshot.progress);
    if (Number.isFinite(progress)) {
      const bucket = Math.floor(progress / 10) * 10;
      if (bucket > lastProgressBucket) {
        lastProgressBucket = bucket;
        console.info(`[release-e2e] ${modelId}: download ${bucket}%`);
      }
    }

    const retryVisible = await retryAction.isVisible().catch(() => false);
    const retryLabel = retryVisible ? (await retryAction.textContent() ?? '').trim() : '';
    if (/^retry$/i.test(retryLabel)) {
      retries += 1;
      if (retries > 3) {
        throw new Error(`${modelId} download failed after 3 visible Retry attempts: ${lastStatus}`);
      }
      console.info(`[release-e2e] ${modelId}: activating visible Retry (${retries}/3)`);
      await retryAction.click();
    }

    await page.waitForTimeout(1_000);
  }

  throw new Error(`${modelId} did not persist to OPFS before timeout: ${lastStatus}`);
}

export async function isModelDownloaded(page: Page, modelId: string): Promise<boolean> {
  return page.evaluate((id) => {
    const sdk = (window as Window & { __RUNANYWHERE_SDK__?: BrowserSDKProbe })
      .__RUNANYWHERE_SDK__;
    if (!sdk) return false;
    try {
      const model = sdk.getModel?.(id);
      if (model?.isDownloaded && model?.localPath) return true;
      const downloaded = sdk.downloadedModels?.();
      return Boolean(downloaded?.models?.some((entry: { id?: string; localPath?: string }) => (
        entry.id === id && Boolean(entry.localPath)
      )));
    } catch {
      return false;
    }
  }, modelId);
}

export async function isModelLoaded(page: Page, modelId: string): Promise<boolean> {
  return page.evaluate((id) => {
    const sdk = (window as Window & { __RUNANYWHERE_SDK__?: BrowserSDKProbe })
      .__RUNANYWHERE_SDK__;
    if (!sdk) return false;
    try {
      const model = sdk.getModel?.(id);
      if (model?.category == null) return false;
      const current = sdk.currentModel?.({
        category: model.category,
        includeModelMetadata: false,
      });
      return current?.modelId === id;
    } catch {
      return false;
    }
  }, modelId);
}

export async function expectSubstantiveText(
  locator: Locator,
  options: { minLength?: number; timeout?: number; forbidden?: RegExp } = {},
): Promise<string> {
  const minLength = options.minLength ?? 12;
  const timeout = options.timeout ?? 10 * 60_000;
  const forbidden = options.forbidden
    ?? /\((?:no response|no transcript|waiting for speech)[^)]*\)|\b(?:failed|error|unavailable)\b/i;
  const pending = /\((?:no response|no transcript|waiting for speech)[^)]*\)|^\s*(?:Thinking)?(?:…|\.\.\.)\s*$/i;
  let substantiveText = '';

  await expect.poll(async () => {
    const text = (await locator.textContent() ?? '').trim();
    pending.lastIndex = 0;
    if (pending.test(text)) return false;
    forbidden.lastIndex = 0;
    if (forbidden.test(text)) {
      throw new Error(`Terminal output from ${locator}: ${text}`);
    }
    if (text.length < minLength) return false;
    substantiveText = text;
    return true;
  }, {
    message: `expected substantive output from ${locator}`,
    timeout,
    intervals: [500, 1_000, 2_000, 5_000],
  }).toBe(true);

  return substantiveText;
}

/**
 * Capture a deliberately induced request failure without weakening the
 * release gate for that URL afterward. The failure still appears in the JSON
 * diagnostics with `expected: true`, and the callback must make a substantive
 * UI assertion (for example, the model row changing to Retry).
 */
export async function withExpectedNetworkFailure<T>(
  page: Page,
  pattern: RegExp,
  action: () => Promise<T>,
): Promise<T> {
  const scope: ExpectedFailureScope = { pattern, matches: 0 };
  const scopes = expectedFailureScopes.get(page) ?? [];
  scopes.push(scope);
  expectedFailureScopes.set(page, scopes);
  try {
    const result = await action();
    expect(scope.matches, `expected an induced network failure matching ${pattern}`).toBeGreaterThan(0);
    return result;
  } finally {
    const active = expectedFailureScopes.get(page) ?? [];
    const index = active.indexOf(scope);
    if (index >= 0) active.splice(index, 1);
  }
}

function attachFailureListeners(page: Page, events: BrowserDiagnostic[]): void {
  page.on('console', (message) => {
    const location = message.location();
    const event: BrowserDiagnostic = {
      at: new Date().toISOString(),
      kind: `console.${message.type()}`,
      message: redact(message.text()),
      ...(location.url ? { url: safeURL(location.url) } : {}),
    };
    markExpectedFailure(page, event);
    events.push(event);
    if (process.env.RA_E2E_BROWSER_LOGS === '1') {
      console.info(`[browser:${message.type()}] ${event.message}`);
    }
  });
  page.on('pageerror', (error) => {
    events.push({
      at: new Date().toISOString(),
      kind: 'pageerror',
      message: redact(error.stack || error.message),
    });
  });
  page.on('requestfailed', (request) => {
    const event: BrowserDiagnostic = {
      at: new Date().toISOString(),
      kind: 'requestfailed',
      message: redact(request.failure()?.errorText || 'request failed'),
      method: request.method(),
      resourceType: request.resourceType(),
      url: safeURL(request.url()),
    };
    markExpectedFailure(page, event);
    events.push(event);
  });
  page.on('response', (response) => {
    if (response.status() < 400) return;
    const request = response.request();
    const event: BrowserDiagnostic = {
      at: new Date().toISOString(),
      kind: 'http',
      message: `${response.status()} ${response.statusText()}`.trim(),
      method: request.method(),
      resourceType: request.resourceType(),
      status: response.status(),
      url: safeURL(response.url()),
    };
    markExpectedFailure(page, event);
    events.push(event);
  });
  page.on('crash', () => {
    events.push({
      at: new Date().toISOString(),
      kind: 'pagecrash',
      message: 'Chromium page crashed',
    });
  });
}

async function collectRuntimeSnapshot(page: Page): Promise<Record<string, unknown>> {
  if (page.isClosed()) return { pageClosed: true };
  return page.evaluate(() => {
    const target = window as Window & {
      __RUNANYWHERE_AI_READY__?: unknown;
      __RUNANYWHERE_SDK__?: BrowserSDKProbe;
    };
    const sdk = target.__RUNANYWHERE_SDK__;
    let downloadedModels: Array<{ id?: string; localPath?: string }> = [];
    let currentModels: Array<{ category: unknown; modelId?: string }> = [];
    try {
      downloadedModels = (sdk?.downloadedModels?.()?.models ?? []).map(
        (model: { id?: string; localPath?: string }) => ({
          id: model.id,
          localPath: model.localPath,
        }),
      );
    } catch {
      // Keep the evidence snapshot available even if the registry probe fails.
    }
    try {
      const categories = new Set(
        (sdk?.listModels?.()?.models ?? [])
          .map((model) => model.category)
          .filter((category) => category != null),
      );
      currentModels = Array.from(categories).map((category) => ({
        category,
        modelId: sdk?.currentModel?.({
          category,
          includeModelMetadata: false,
        })?.modelId,
      })).filter((model) => Boolean(model.modelId));
    } catch {
      // Component snapshots are supporting evidence, not a reason to hide the
      // primary diagnostics when one category probe is unavailable.
    }
    return {
      url: window.location.href.split('?')[0],
      readiness: target.__RUNANYWHERE_AI_READY__,
      sdkInitialized: sdk?.isInitialized === true,
      crossOriginIsolated: window.crossOriginIsolated,
      activePanel: document.querySelector('.tab-panel.active')?.id ?? null,
      theme: document.documentElement.dataset.theme ?? null,
      localStorageKeys: Object.keys(localStorage),
      downloadedModels,
      currentModels,
    };
  }).catch((error) => ({ snapshotError: redact(String(error)) }));
}

async function attachJSON(testInfo: TestInfo, name: string, value: unknown): Promise<void> {
  await testInfo.attach(name, {
    body: redact(JSON.stringify(value, null, 2)),
    contentType: 'application/json',
  });
}

function isUnexpectedFailure(event: BrowserDiagnostic): boolean {
  if (event.expected) return false;
  if (isAllowlisted(event)) return false;
  const fatalWarning = event.kind === 'console.warning' && (
    /Panel .* on(?:Activate|Deactivate) error/i.test(event.message)
    || /WebGPU .*?(?:failed|retrying|CPU WASM artifact)/i.test(event.message)
    || /(?:audio )?playback failed|voice turn failed|pipeline recommendation failed/i.test(event.message)
    || /backend failed to register|teardown failed/i.test(event.message)
    || /model-ready callback threw|listener threw|capability probe failed/i.test(event.message)
  );
  return fatalWarning
    || event.kind === 'pageerror'
    || event.kind === 'pagecrash'
    || event.kind === 'requestfailed'
    || event.kind === 'http'
    || event.kind === 'console.error';
}

function markExpectedFailure(page: Page, event: BrowserDiagnostic): void {
  const scopes = expectedFailureScopes.get(page) ?? [];
  for (const scope of scopes) {
    scope.pattern.lastIndex = 0;
    const haystack = `${event.url ?? ''}\n${event.message}`;
    const resourceMatches = scope.pattern.test(haystack);
    if (resourceMatches) {
      event.expected = true;
      scope.matches += 1;
      return;
    }
  }
}

/** Attach credential-safe diagnostics to an additional page (for CPU fallback). */
export function observeBrowserDiagnostics(page: Page): BrowserDiagnostic[] {
  const events: BrowserDiagnostic[] = [];
  attachFailureListeners(page, events);
  return events;
}

export function unexpectedBrowserDiagnostics(
  events: readonly BrowserDiagnostic[],
): BrowserDiagnostic[] {
  return events.filter(isUnexpectedFailure);
}

async function scrubPasswordInputs(page: Page): Promise<void> {
  if (page.isClosed()) return;
  await page.locator('input[type="password"]').evaluateAll((inputs) => {
    for (const input of inputs) {
      if (!(input instanceof HTMLInputElement) || input.value.length === 0) continue;
      input.value = '';
      input.dispatchEvent(new Event('input', { bubbles: true }));
      input.dispatchEvent(new Event('change', { bubbles: true }));
    }
  }).catch(() => undefined);
}

function isAllowlisted(event: BrowserDiagnostic): boolean {
  if (/\bNO_COLOR\b/i.test(event.message)) return true;
  if (/model assignment base URL is not configured/i.test(event.message)) return true;
  if (
    event.kind === 'http'
    && event.status === 404
    && /\/(?:favicon\.ico|\.well-known\/appspecific\/com\.chrome\.devtools\.json)$/i.test(event.url ?? '')
  ) {
    return true;
  }
  return false;
}

function formatDiagnostic(event: BrowserDiagnostic): string {
  const request = event.method ? ` ${event.method}` : '';
  const target = event.url ? ` ${event.url}` : '';
  return `[${event.kind}]${request}${target}: ${event.message}`;
}

function safeURL(raw: string): string {
  try {
    const url = new URL(raw);
    url.username = '';
    url.password = '';
    url.search = '';
    url.hash = '';
    return url.toString();
  } catch {
    return raw.split(/[?#]/, 1)[0];
  }
}

function redact(value: string): string {
  return value
    .replace(/\bBearer\s+[^\s"']+/gi, 'Bearer [REDACTED]')
    .replace(/\bsk-[A-Za-z0-9_-]{8,}\b/g, '[REDACTED-KEY]')
    .replace(/((?:api[-_ ]?key|authorization)["']?\s*[:=]\s*["']?)[^\s,"'}]+/gi, '$1[REDACTED]');
}

/**
 * Characterizes which `LoadOptions` fields `models.load()` rejects at
 * preflight because the commons load ABI has no wire path for them yet
 * (PR #605 review issue 8). Per the v4 public API spec, silently dropping
 * an accepted field is forbidden, so unsupported knobs are reported for
 * `models.load` to throw on rather than merely warn about.
 */

import { unsupportedLoadOptionKeys } from '../../../../src/Public/Api/LoadOptionsSupport';
import { InferenceFramework } from '@runanywhere/proto-ts/model_types';

describe('unsupportedLoadOptionKeys', () => {
  it('reports nothing for undefined options', () => {
    expect(unsupportedLoadOptionKeys(undefined)).toEqual([]);
  });

  it('does not report framework, which does reach commons', () => {
    expect(
      unsupportedLoadOptionKeys({
        framework: InferenceFramework.INFERENCE_FRAMEWORK_LLAMA_CPP,
      })
    ).toEqual([]);
  });

  it('does not report a single backendPreferences entry', () => {
    expect(
      unsupportedLoadOptionKeys({
        backendPreferences: [{ backend: InferenceFramework.INFERENCE_FRAMEWORK_LLAMA_CPP }],
      })
    ).toEqual([]);
  });

  it('reports contextLength, threads, and accelerator individually', () => {
    expect(unsupportedLoadOptionKeys({ contextLength: 4096 })).toEqual([
      'contextLength',
    ]);
    expect(unsupportedLoadOptionKeys({ threads: 4 })).toEqual(['threads']);
    expect(unsupportedLoadOptionKeys({ accelerator: 'gpu' })).toEqual(['accelerator']);
    expect(unsupportedLoadOptionKeys({ useGpu: true })).toEqual(['accelerator']);
  });

  it('reports multiple backendPreferences entries', () => {
    const keys = unsupportedLoadOptionKeys({
      backendPreferences: [
        { backend: InferenceFramework.INFERENCE_FRAMEWORK_LLAMA_CPP },
        { backend: InferenceFramework.INFERENCE_FRAMEWORK_ONNX },
      ],
    });
    expect(keys).toHaveLength(1);
    expect(keys[0]).toMatch(/^backendPreferences/);
  });

  it('combines every unsupported knob in a stable order', () => {
    expect(
      unsupportedLoadOptionKeys({
        contextLength: 4096,
        threads: 4,
        accelerator: 'cpu',
      })
    ).toEqual(['contextLength', 'threads', 'accelerator']);
  });
});

/**
 * @file test_auth_sdk_events.cpp
 * @brief Auth manager coverage for canonical SDKEvent AuthEvent emissions.
 */

#include <cstdio>
#include <cstring>

#include "rac/core/rac_error.h"
#include "rac/foundation/rac_proto_buffer.h"
#include "rac/infrastructure/events/rac_sdk_event_stream.h"
#include "rac/infrastructure/network/rac_auth_manager.h"

#if defined(RAC_HAVE_PROTOBUF)
#include "sdk_events.pb.h"
#endif

namespace {

int test_count = 0;
int fail_count = 0;

#define CHECK(cond, label)                                                                       \
    do {                                                                                         \
        ++test_count;                                                                            \
        if (!(cond)) {                                                                           \
            ++fail_count;                                                                        \
            std::fprintf(stderr, "  FAIL: %s (%s:%d) - %s\n", label, __FILE__, __LINE__, #cond); \
        } else {                                                                                 \
            std::fprintf(stdout, "  ok:   %s\n", label);                                         \
        }                                                                                        \
    } while (0)

#if defined(RAC_HAVE_PROTOBUF)

bool poll_event(runanywhere::v1::SDKEvent* out) {
    rac_proto_buffer_t buffer;
    rac_proto_buffer_init(&buffer);
    const rac_result_t rc = rac_sdk_event_poll(&buffer);
    if (rc != RAC_SUCCESS) {
        return false;
    }
    const bool parsed = out->ParseFromArray(buffer.data, static_cast<int>(buffer.size));
    rac_proto_buffer_free(&buffer);
    return parsed;
}

constexpr const char* kAuthResponse =
    R"({"access_token":"access-1","refresh_token":"refresh-1","device_id":"device-1","user_id":"user-1","organization_id":"org-1","token_type":"bearer","expires_in":3600})";

constexpr const char* kRefreshResponse =
    R"({"access_token":"access-2","refresh_token":"refresh-2","device_id":"device-1","user_id":"user-1","organization_id":"org-1","token_type":"bearer","expires_in":7200})";

void expect_auth_envelope(const runanywhere::v1::SDKEvent& event,
                          runanywhere::v1::AuthEventKind kind, const char* operation) {
    CHECK(!event.id().empty(), "auth SDKEvent has id");
    CHECK(event.timestamp_ms() > 0, "auth SDKEvent has timestamp");
    CHECK(event.category() == runanywhere::v1::EVENT_CATEGORY_AUTH,
          "auth SDKEvent uses auth category");
    CHECK(event.source() == "cpp", "auth SDKEvent source is cpp");
    CHECK(event.operation_id() == operation, "auth SDKEvent carries operation id");
    CHECK(event.has_auth(), "auth SDKEvent uses AuthEvent payload");
    CHECK(event.auth().kind() == kind, "auth SDKEvent carries expected AuthEvent kind");
    CHECK(event.auth().provider() == "runanywhere", "auth SDKEvent carries provider");
    CHECK(event.auth().scope() == "sdk", "auth SDKEvent carries scope");
}

#endif

}  // namespace

int main() {
    std::fprintf(stdout, "test_auth_sdk_events\n");

#if !defined(RAC_HAVE_PROTOBUF)
    std::fprintf(stdout, "  skip: auth SDKEvent tests (no protobuf)\n");
    return 0;
#else
    rac_auth_init(nullptr);
    rac_sdk_event_clear_queue();

    int rc = rac_auth_handle_authenticate_response(kAuthResponse);
    CHECK(rc == 0, "authenticate response is accepted");
    CHECK(rac_auth_is_authenticated(), "auth manager becomes authenticated");
    CHECK(std::strcmp(rac_auth_get_access_token(), "access-1") == 0,
          "auth manager stores access token");

    runanywhere::v1::SDKEvent auth_event;
    CHECK(poll_event(&auth_event), "authenticate response publishes SDKEvent");
    expect_auth_envelope(auth_event, runanywhere::v1::AUTH_EVENT_KIND_SUCCEEDED,
                         "auth.authenticate");
    CHECK(auth_event.severity() == runanywhere::v1::ERROR_SEVERITY_INFO,
          "authenticate success severity is info");
    CHECK(auth_event.auth().subject_id() == "user-1", "authenticate event carries subject");
    const auto device_property = auth_event.properties().find("device_id");
    CHECK(device_property != auth_event.properties().end() && device_property->second == "device-1",
          "authenticate event carries device id property");

    rac_sdk_event_clear_queue();
    rc = rac_auth_handle_refresh_response(kRefreshResponse);
    CHECK(rc == 0, "refresh response is accepted");
    CHECK(std::strcmp(rac_auth_get_access_token(), "access-2") == 0,
          "refresh updates access token");

    runanywhere::v1::SDKEvent refresh_event;
    CHECK(poll_event(&refresh_event), "refresh response publishes SDKEvent");
    expect_auth_envelope(refresh_event, runanywhere::v1::AUTH_EVENT_KIND_TOKEN_REFRESHED,
                         "auth.refresh");
    CHECK(refresh_event.severity() == runanywhere::v1::ERROR_SEVERITY_INFO,
          "refresh severity is info");

    rac_sdk_event_clear_queue();
    rc = rac_auth_handle_authenticate_response(R"({"access_token":"missing-refresh"})");
    CHECK(rc == -1, "invalid authenticate response is rejected");

    runanywhere::v1::SDKEvent failed_event;
    CHECK(poll_event(&failed_event), "invalid authenticate response publishes SDKEvent");
    expect_auth_envelope(failed_event, runanywhere::v1::AUTH_EVENT_KIND_FAILED,
                         "auth.authenticate");
    CHECK(failed_event.severity() == runanywhere::v1::ERROR_SEVERITY_ERROR,
          "auth failure severity is error");
    CHECK(failed_event.has_error(), "auth failure carries SDKError");
    CHECK(failed_event.error().c_abi_code() == RAC_ERROR_AUTHENTICATION_FAILED,
          "auth failure preserves C ABI error code");
    CHECK(failed_event.auth().error() == "Authentication response is invalid",
          "auth failure carries parse failure message");

    rac_auth_clear();
    rac_sdk_event_clear_queue();

    std::fprintf(stdout, "  %d checks, %d failures\n", test_count, fail_count);
    return fail_count == 0 ? 0 : 1;
#endif
}

/**
 * @file test_auth_secure_storage.cpp
 * @brief Fail-closed auth persistence and secure-storage status coverage.
 */

#include <cstdio>
#include <cstring>
#include <string>
#include <unordered_map>

#include "rac/core/rac_error.h"
#include "rac/infrastructure/network/rac_auth_manager.h"

namespace {

int test_count = 0;
int fail_count = 0;

#define CHECK(cond, label)                                                                       \
    do {                                                                                         \
        ++test_count;                                                                            \
        if (!(cond)) {                                                                           \
            ++fail_count;                                                                        \
            std::fprintf(stderr, "  FAIL: %s (%s:%d) - %s\n", label, __FILE__, __LINE__, #cond); \
        } else {                                                                                 \
            std::fprintf(stdout, "  ok:   %s\n", label);                                         \
        }                                                                                        \
    } while (0)

struct FakeSecureStorage {
    std::unordered_map<std::string, std::string> values;
    std::string failing_store_key;
    std::string failing_retrieve_key;
    std::string failing_delete_key;
    int delete_calls = 0;
};

int store_value(const char* key, const char* value, void* context) {
    auto* storage = static_cast<FakeSecureStorage*>(context);
    if (key == nullptr || value == nullptr || storage == nullptr) {
        return -1;
    }
    if (storage->failing_store_key == key) {
        return -1;
    }
    storage->values[key] = value;
    return 0;
}

int retrieve_value(const char* key, char* out_value, size_t buffer_size, void* context) {
    auto* storage = static_cast<FakeSecureStorage*>(context);
    if (key == nullptr || out_value == nullptr || buffer_size == 0 || storage == nullptr) {
        return RAC_ERROR_INVALID_ARGUMENT;
    }
    if (storage->failing_retrieve_key == key) {
        return RAC_ERROR_SECURE_STORAGE_FAILED;
    }
    const auto found = storage->values.find(key);
    if (found == storage->values.end()) {
        return RAC_ERROR_FILE_NOT_FOUND;
    }
    if (found->second.size() + 1 > buffer_size) {
        return RAC_ERROR_BUFFER_TOO_SMALL;
    }
    std::memcpy(out_value, found->second.c_str(), found->second.size() + 1);
    return static_cast<int>(found->second.size());
}

int delete_value(const char* key, void* context) {
    auto* storage = static_cast<FakeSecureStorage*>(context);
    if (key == nullptr || storage == nullptr) {
        return -1;
    }
    ++storage->delete_calls;
    if (storage->failing_delete_key == key) {
        return -1;
    }
    storage->values.erase(key);
    return 0;
}

rac_secure_storage_t make_storage(FakeSecureStorage* context) {
    rac_secure_storage_t storage = {};
    storage.store = store_value;
    storage.retrieve = retrieve_value;
    storage.delete_key = delete_value;
    storage.context = context;
    return storage;
}

constexpr const char* kAuthResponse =
    R"({"access_token":"access-1","refresh_token":"refresh-1","device_id":"device-1","user_id":"user-1","organization_id":"org-1","token_type":"bearer","expires_in":3600})";
constexpr const char* kAuthResponseWithoutOptionalIdentity =
    R"({"access_token":"access-2","refresh_token":"refresh-2","token_type":"bearer","expires_in":3600})";

}  // namespace

int main() {
    std::fprintf(stdout, "test_auth_secure_storage\n");

    FakeSecureStorage fake;
    rac_secure_storage_t storage = make_storage(&fake);

    rac_auth_init(&storage);
    CHECK(rac_auth_load_stored_tokens() == RAC_ERROR_FILE_NOT_FOUND,
          "clean access-token miss stays distinct");

    fake.failing_retrieve_key = RAC_KEY_ACCESS_TOKEN;
    CHECK(rac_auth_load_stored_tokens() == RAC_ERROR_SECURE_STORAGE_FAILED,
          "authenticated access-token read failure propagates");
    fake.failing_retrieve_key.clear();

    fake.values[RAC_KEY_ACCESS_TOKEN] = "";
    CHECK(rac_auth_load_stored_tokens() == RAC_ERROR_SECURE_STORAGE_FAILED,
          "present empty access token is storage corruption, not a clean miss");

    fake.values[RAC_KEY_ACCESS_TOKEN] = "stored-access";
    fake.values[RAC_KEY_REFRESH_TOKEN] = "";
    CHECK(rac_auth_load_stored_tokens() == RAC_ERROR_SECURE_STORAGE_FAILED,
          "present empty optional token is storage corruption, not omission");
    fake.values.erase(RAC_KEY_REFRESH_TOKEN);
    CHECK(rac_auth_load_stored_tokens() == RAC_SUCCESS,
          "optional clean misses do not block token restore");
    CHECK(rac_auth_is_authenticated(), "successful restore authenticates state");
    CHECK(std::strcmp(rac_auth_get_access_token(), "stored-access") == 0,
          "successful restore retains exact access token");

    rac_auth_init(&storage);
    fake.values.clear();
    fake.failing_store_key = RAC_KEY_REFRESH_TOKEN;
    fake.delete_calls = 0;
    CHECK(rac_auth_handle_authenticate_response(kAuthResponse) == RAC_ERROR_SECURE_STORAGE_FAILED,
          "authentication reports durable persistence failure");
    CHECK(!rac_auth_is_authenticated(), "persistence failure clears in-memory auth state");
    CHECK(fake.delete_calls == 5, "persistence rollback attempts every auth-key deletion");
    CHECK(fake.values.empty(), "persistence rollback removes partial durable state");

    fake.failing_store_key.clear();
    fake.failing_delete_key.clear();
    fake.delete_calls = 0;
    CHECK(rac_auth_handle_authenticate_response(kAuthResponse) == RAC_SUCCESS,
          "authentication succeeds when every secure write commits");
    fake.delete_calls = 0;
    CHECK(rac_auth_handle_refresh_response(kAuthResponseWithoutOptionalIdentity) == RAC_SUCCESS,
          "refresh succeeds when optional identity is omitted");
    CHECK(fake.delete_calls == 3, "refresh deletes every omitted optional identity value");
    CHECK(fake.values.size() == 2 && fake.values.count(RAC_KEY_ACCESS_TOKEN) == 1 &&
              fake.values.count(RAC_KEY_REFRESH_TOKEN) == 1,
          "durable auth snapshot contains no stale optional identity");

    fake.failing_delete_key = RAC_KEY_REFRESH_TOKEN;
    fake.delete_calls = 0;
    CHECK(rac_auth_clear() == RAC_ERROR_SECURE_STORAGE_FAILED,
          "logout reports a durable deletion failure");
    CHECK(fake.delete_calls == 5, "logout attempts every deletion after one fails");
    CHECK(!rac_auth_is_authenticated(), "logout always clears process-local auth state");
    CHECK(fake.values.size() == 1 && fake.values.count(RAC_KEY_REFRESH_TOKEN) == 1,
          "only the injected failed deletion remains persisted");

    fake.failing_delete_key.clear();
    CHECK(rac_auth_clear() == RAC_SUCCESS, "logout succeeds after durable storage recovers");
    CHECK(fake.values.empty(), "successful logout removes all persisted auth state");

    // -------------------------------------------------------------------
    // PR #605 review issue #6: access-only storage cannot report
    // authenticated forever. rac_auth_load_stored_tokens() always sets
    // token_expires_at = 0 (expiry unknown after a restore) — the fix lives
    // in the runtime staleness check (rac_auth_needs_refresh() /
    // rac_auth_get_valid_token()), not at load time, so the pre-existing
    // "optional clean misses do not block token restore" contract above
    // must keep passing unchanged (it does: access-only restore still
    // succeeds and authenticates).
    // -------------------------------------------------------------------

    // Access-only restore (57856ce / 22946cb regression path): no refresh
    // token was ever persisted (legacy storage). is_authenticated() is
    // true, but the token must be reported stale so callers do not trust it
    // forever — get_valid_token must signal "needs refresh" rather than
    // handing back the possibly-expired access token.
    rac_auth_init(&storage);
    fake.values.clear();
    fake.values[RAC_KEY_ACCESS_TOKEN] = "legacy-access-only";
    CHECK(rac_auth_load_stored_tokens() == RAC_SUCCESS,
          "access-only restore still succeeds (no load-time regression)");
    CHECK(rac_auth_is_authenticated(), "access-only restore authenticates state");
    CHECK(rac_auth_needs_refresh(),
          "access-only restore must report stale, not authenticated forever");
    {
        const char* token = nullptr;
        bool needs_refresh = false;
        CHECK(rac_auth_get_valid_token(&token, &needs_refresh) == 1,
              "access-only restore signals refresh needed, not a valid token");
        CHECK(needs_refresh, "access-only restore sets out_needs_refresh");
        CHECK(token == nullptr, "access-only restore does not hand back the stale token");
    }

    // Valid refresh-pair restore: both tokens were persisted. Expiry is
    // still unknown immediately after a restore (by design — the in-memory
    // expiry timestamp is never persisted), so this also reports "needs
    // refresh" once — but unlike the access-only case, a real refresh_token
    // exists so the caller's refresh actually can succeed instead of
    // failing closed into a full re-authenticate.
    rac_auth_init(&storage);
    fake.values.clear();
    fake.values[RAC_KEY_ACCESS_TOKEN] = "restored-access";
    fake.values[RAC_KEY_REFRESH_TOKEN] = "restored-refresh";
    CHECK(rac_auth_load_stored_tokens() == RAC_SUCCESS, "valid refresh-pair restore succeeds");
    CHECK(rac_auth_is_authenticated(), "valid refresh-pair restore authenticates state");
    CHECK(rac_auth_needs_refresh(),
          "valid refresh-pair restore also revalidates once (unknown expiry)");
    {
        const char* token = nullptr;
        bool needs_refresh = false;
        CHECK(rac_auth_get_valid_token(&token, &needs_refresh) == 1,
              "valid refresh-pair restore signals refresh needed for the same reason");
        CHECK(needs_refresh, "valid refresh-pair restore sets out_needs_refresh");
    }
    CHECK(std::strcmp(rac_auth_get_refresh_token(), "restored-refresh") == 0,
          "valid refresh-pair restore retains the refresh token a real refresh needs");

    // Previously regressed model-assignment/auth path (22946cb): a freshly
    // *authenticated* (not restored) session has a known, far-future expiry
    // and must NOT be treated as needing refresh — this is the fast path
    // perform_authentication()/rac_sdk_retry_http_proto() share with phase-2
    // model-assignment/registration, and the fix here must not make a
    // healthy session look stale.
    rac_auth_init(&storage);
    fake.values.clear();
    fake.failing_store_key.clear();
    CHECK(rac_auth_handle_authenticate_response(kAuthResponse) == RAC_SUCCESS,
          "fresh authenticate succeeds");
    CHECK(!rac_auth_needs_refresh(),
          "a freshly authenticated session with a healthy expiry is not stale");
    {
        const char* token = nullptr;
        bool needs_refresh = false;
        CHECK(rac_auth_get_valid_token(&token, &needs_refresh) == 0,
              "a freshly authenticated session returns its valid token immediately");
        CHECK(!needs_refresh, "a freshly authenticated session does not request a refresh");
        CHECK(token != nullptr && std::strcmp(token, "access-1") == 0,
              "a freshly authenticated session's valid token is the one just issued");
    }

    rac_auth_clear();

    std::fprintf(stdout, "  %d checks, %d failures\n", test_count, fail_count);
    return fail_count == 0 ? 0 : 1;
}

